    "schemas": {
      "type": "object",
      "properties": {
        "baseUri": {
          "type": "string"
        },
        "baseType": {
          "type": "string"
        },
        "types": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "relations": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "equivalence": {
          "type": "string"
        }
      },
      "additionalProperties": false,
      "required": [
        "baseUri",
        "baseType",
        "types",
        "relations",
        "equivalence"
      ]
    },
    "api": {
      "type": "object",
      "properties": {
        "defaultPathRelation": {
          "type": "string"
        },
        "hairRelations": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "exampleUrls": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "bindHost": {
          "type": "string"
        },
        "bindPort": {
          "type": "integer"
        },
        "baseUrl": {
          "type": "string"
        },
        "dataDir": {
          "type": "string"
        },
        "admin": {
          "type": "object",
          "properties": {
            "name": {
              "type": "string"
            },
            "password": {
              "type": "string"
            }
          }
        }
      },
      "additionalProperties": false,
      "required": [
        "bindHost",
        "bindPort",
        "baseUrl",
        "dataDir",
        "admin",
        "defaultPathRelation",
        "hairRelations"
      ]
    },
    "stats": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "enabled",
        "cronExpression"
      ],
      "properties": {
        "enabled": {
          "type": "boolean"
        },
        "cronExpression": {
          "type": "string"
        }
      }
    },
    "redis": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "host",
        "port",
        "queue",
        "maxQueueSize"
      ],
      "properties": {
        "host": {
          "type": "string"
        },
        "port": {
          "type": "integer"
        },
        "queue": {
          "type": "string"
        },
        "maxQueueSize": {
          "type": "integer"
        }
      }
    },
    "elasticsearch": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "host",
        "port"
      ],
      "properties": {
        "host": {
          "type": "string"
        },
        "port": {
          "type": "integer"
        }
      }
    },
    "neo4j": {
      "type": "object",
      "properties": {
        "host": {
          "type": "string"
        },
        "port": {
          "type": "integer"
        },
        "user": {
          "type": [
            "string",
            "null"
          ]
        },
        "password": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "additionalProperties": false,
      "required": [
        "host",
        "port",
        "user",
        "password"
      ]
    },
    "core": {
      "type": "object",
      "properties": {
        "batchSize": {
          "type": "integer"
        },
        "batchTimeout": {
          "type": "integer"
        }
      },
      "additionalProperties": false,
      "required": [
        "batchSize",
        "batchTimeout"
      ]
    },
    "viewer": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "language",
        "mode",
        "logo",
        "color",
        "suffixFilters"
      ],
      "properties": {
        "language": {
          "type": "string"
        },
        "mode": {
          "type": "string",
          "enum": [
            "simple",
            "advanced"
          ]
        },
        "logo": {
          "type": [
            "string",
            "null"
          ]
        },
        "color": {
          "type": "string"
        },
        "suffixFilters": {
          "type": "array"
        }
      }
    },
    "data": {
      "type": "object",
      "properties": {
        "geonames": {
