          "type": "object",
          "properties": {
            "parents": {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          }
        },
        "bag": {
          "type": "object",
          "properties": {
            "db": {
              "type": "object",
              "properties": {
                "host": {
                  "type": "string"
                },
                "port": {
                  "type": "integer"
                },
                "user": {
                  "type": "string"
                },
                "password": {
                  "type": "string"
                },
                "database": {
                  "type": "string"
                }
              }
            }
          }
