        "s3": {
          "type": "object",
          "properties": {
            "region": {
              "type": [
                "string",
                "null"
              ]
            },
            "accessKeyId": {
              "type": [
                "string",
                "null"
              ]
            },
            "secretAccessKey": {
              "type": [
                "string",
                "null"
              ]
            },
            "buckets": {
              "type": [
                "array",
                "null"
              ],
              "items": {
                "type": "string"
              }
            }
          },
          "additionalProperties": false
        },
        "diffTool": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    "logo": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "additionalProperties": false,
  "required": [
    "schemas",
    "stats",
    "api",
    "redis",
    "elasticsearch",
    "neo4j",
    "viewer",
    "data",
    "import",
    "logo"
  ]
}

{
