                                    "type": [
                                        "string",
                                        "number",
                                        "boolean"
                                    ]
                                }
                            },
                            "uri": {
                                "type": "string",
                                "title": "Annotation URI",
                                "description": "URI for Annotation",
                                "format": "uri",
                                "items": {
                                    "type": "string",
                                    "format": "uri"
                                }
                            }
                        }
                    }
                },
                "references": {
                    "type": [
                        "object",
                        "null"
                    ],
                    "title": "References",
                    "description": "The references section identifies annotation and namespace URIs.",
                    "properties": {
                        "annotations": {
                            "type": [
                                "array",
                                "null"
                            ],
                            "title": "Annotation references",
